package blockbranch.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.levelgen.structure.*;
/** First actual selected layouts; focused functionality and immutable saved-world checks. */
public final class ReimaginedQualification {
 static final int[][] SITES={{1,228504,17,-267736},{2,-701960,532,270984}};static int index;static boolean prepared,done;static long started,readyAt;static BoundingBox box;static StructureStart start;static List<ChunkPos> forced;static final List<Object> reports=new ArrayList<>();
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents.END_SERVER_TICK.register(server->{if(done)return;try{var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();require(g.reimaginedDefinition()>0&&g.nativeOrdinaryDefinition()==1,"New102 retains native ordinary101");var site=SITES[index];String name=site[0]==1?"crypt":"pyramid";boolean reload=Files.exists(Path.of(name+"-saved.json"));var context=net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level);
 if(!prepared){if(CryptAdmissionProbe.enabled())CryptAdmissionProbe.begin(level);started=System.nanoTime();var plan=g.reimagined(level.getChunkSource().randomState()).forStart(site[0],site[1]>>4,site[3]>>4).orElseThrow();require(plan.y()==site[2],"Actual frozen selected fit");CryptAdmissionProbe.mark("regional-plan");var holder=level.registryAccess().lookupOrThrow(Registries.STRUCTURE).getOrThrow(ReimaginedStructures.key(site[0]));var chunk=level.getChunk(site[1]>>4,site[3]>>4,net.minecraft.world.level.chunk.status.ChunkStatus.STRUCTURE_STARTS);start=level.structureManager().getStartForStructure(holder.value(),chunk);require(start!=null&&start.isValid(),"Native production structure start "+name);CryptAdmissionProbe.mark("structure-start");box=start.getBoundingBox();forced=new ArrayList<>();for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)forced.add(new ChunkPos(x,z));if(Boolean.getBoolean("blockbranch.reimaginedReverse"))Collections.reverse(forced);for(var c:forced){level.setChunkForced(c.x(),c.z(),true);CryptAdmissionProbe.mark("forced:"+c.x()+","+c.z());}readyAt=System.nanoTime();if(CryptAdmissionProbe.enabled())CryptAdmissionProbe.endAdmission(level);prepared=true;return;}
 if(forced.stream().anyMatch(c->!level.areEntitiesLoaded(c.pack()))){require(System.nanoTime()-readyAt<120_000_000_000L,"Native entity admission deadline");return;}if(CryptAdmissionProbe.enabled())CryptAdmissionProbe.entitiesReady(level);if(System.nanoTime()-readyAt<1_000_000_000L)return;
 var chests=new ArrayList<ChestBlockEntity>();var archaeology=new ArrayList<BrushableBlockEntity>();var spawners=new ArrayList<SpawnerBlockEntity>();int tnt=0,plate=0;for(var at:BlockPos.betweenClosed(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ())){var state=level.getBlockState(at);if(state.is(Blocks.TNT))tnt++;if(state.is(Blocks.STONE_PRESSURE_PLATE))plate++;var be=state.hasBlockEntity()?level.getBlockEntity(at):null;if(be instanceof ChestBlockEntity c)chests.add(c);if(be instanceof BrushableBlockEntity b)archaeology.add(b);if(be instanceof SpawnerBlockEntity s)spawners.add(s);}
 var row=new LinkedHashMap<String,Object>();row.put("name",name);row.put("site",site);row.put("bounds",List.of(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()));row.put("pieces",start.getPieces().stream().map(p->p.createTag(context).toString()).toList());row.put("admissionNanos",readyAt-started);row.put("chests",chests.size());row.put("archaeology",archaeology.size());row.put("spawners",spawners.stream().map(s->s.saveWithoutMetadata(level.registryAccess()).toString()).toList());row.put("tnt",tnt);row.put("pressurePlates",plate);row.put("reload",reload);row.put("connectedRoutePositions",ReimaginedRoutes.verify(level,(ReimaginedLayoutPiece)start.getPieces().stream().filter(p->p instanceof ReimaginedLayoutPiece).findFirst().orElseThrow()));
 require(start.getPieces().stream().anyMatch(p->p instanceof ReimaginedLayoutPiece),"Versioned architectural layout piece");if(site[0]==1){require(spawners.size()==1,"One original native monster-room spawner");require(chests.size()<=2,"Original native room chest attempt cap");var data=spawners.getFirst().saveWithoutMetadata(level.registryAccess()).toString();require(data.contains("minecraft:zombie")||data.contains("minecraft:skeleton")||data.contains("minecraft:spider"),"Original native spawner type");}else{require(chests.size()==4&&tnt==9&&plate==1,"Native pyramid four chests/nine TNT/one plate");require(archaeology.size()>=(reload?5:6)&&archaeology.size()<=8,"Native archaeology quota");require(start.getPieces().getFirst() instanceof net.minecraft.world.level.levelgen.structure.structures.DesertPyramidPiece,"Native pyramid functional core");}
 if(reload){var old=com.google.gson.JsonParser.parseString(Files.readString(Path.of(name+"-saved.json"))).getAsJsonObject();require(ColdRuinGrounding.hash(level,box).equals(old.get("hash").getAsString()),"Exact saved architecture "+name);var p=NativeOrdinaryQualification.pos(old.getAsJsonArray("edit"));require(level.getBlockState(p).is(Blocks.OAK_PLANKS),"Player repair retained");for(var c:chests)require(c.getLootTable()==null&&c.isEmpty(),"Consumed original loot stays consumed");if(old.has("brush")){var at=NativeOrdinaryQualification.pos(old.getAsJsonObject("brush").getAsJsonArray("position"));require(level.getBlockState(at).is(Blocks.SAND)&&level.getBlockEntity(at)==null,"Consumed native archaeology retained");}}
 else{row.put("lootTables",chests.stream().map(c->{require(c.getLootTable()!=null,"Original native loot table");return c.getLootTable().identifier().toString();}).toList());for(var c:chests){c.unpackLootTable(null);c.clearContent();c.setChanged();}if(!archaeology.isEmpty())row.put("brush",NativeOrdinaryQualification.brush(level,archaeology.stream().max(Comparator.comparingInt(b->b.getBlockPos().getY())).orElseThrow().getBlockPos()));var edit=new BlockPos(box.minX(),box.minY()+1,box.minZ());level.setBlock(edit,Blocks.OAK_PLANKS.defaultBlockState(),3);row.put("edit",List.of(edit.getX(),edit.getY(),edit.getZ()));row.put("hash",ColdRuinGrounding.hash(level,box));String reference=System.getProperty("blockbranch.reimaginedReference","");if(!reference.isEmpty()){var old=com.google.gson.JsonParser.parseString(Files.readString(Path.of(reference).resolve(name+"-saved.json"))).getAsJsonObject();require(row.get("hash").equals(old.get("hash").getAsString()),"Reverse clipped chunk order preserves exact complete architecture "+name);}write(name+"-saved.json",row);}
 reports.add(row);write(reload?"reopen.json":"fresh.json",reports);for(var c:forced)level.setChunkForced(c.x(),c.z(),false);server.saveEverything(false,true,true);prepared=false;if(++index==(CryptAdmissionProbe.enabled()?1:SITES.length)){Files.writeString(Path.of("result.txt"),"PASS");done=true;server.halt(false);}
 }catch(Throwable t){done=true;blockbranch.Blockbranch.LOGGER.error("REIMAGINED_NATIVE_FAIL",t);try{Files.writeString(Path.of("result.txt"),"FAIL "+t);}catch(Exception ignored){}server.halt(false);}});}
 static void require(boolean yes,String message){if(!yes)throw new AssertionError(message);}static void write(String name,Object value)throws Exception{Files.writeString(Path.of(name),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(value));}
}
